const money = (value: number) => `$${value.toFixed(2)}`;
const readStorage = <T,>(key: string, fallback: T): T => {
  try { return JSON.parse(localStorage.getItem(key) || '') as T; } catch { return fallback; }
};

function Header({ cartCount, wishlistCount, onCart, onSearch }: { cartCount:number; wishlistCount:number; onCart:()=>void; onSearch:()=>void }) {
  const [menu, setMenu] = useState(false);
  const [dark, setDark] = useState(() => localStorage.getItem('aura-theme') === 'dark');
  const [, navigate] = useLocation();
  useEffect(() => { document.documentElement.classList.toggle('dark', dark); localStorage.setItem('aura-theme', dark ? 'dark' : 'light'); }, [dark]);
  const nav = (href: string) => { setMenu(false); navigate(href); };
  return <header className="sticky top-0 z-40 border-b hairline bg-[hsl(var(--background)/.9)] backdrop-blur-xl">
    <div className="mx-auto flex h-[72px] max-w-[1440px] items-center justify-between px-5 md:px-10">
      <button className="md:hidden" onClick={() => setMenu(!menu)} aria-label="Open navigation" data-testid="button-open-menu"><Menu size={20}/></button>
      <Link href="/" className="group flex items-center gap-3" data-testid="link-home">
        <span className="grid size-8 place-items-center border border-[hsl(var(--accent))] text-[hsl(var(--accent))]"><span className="serif text-lg italic">A</span></span>
        <span className="text-[13px] font-bold tracking-[.34em]">AURA SCENT</span>
      </Link>
      <nav className="hidden items-center gap-9 text-[11px] font-semibold uppercase tracking-[.17em] md:flex">
        <Link href="/shop" className="transition-colors hover:text-[hsl(var(--accent))]" data-testid="link-shop">Shop</Link>
        <Link href="/collections" className="transition-colors hover:text-[hsl(var(--accent))]" data-testid="link-collections">Collections</Link>
        <Link href="/quiz" className="transition-colors hover:text-[hsl(var(--accent))]" data-testid="link-quiz">Find your scent</Link>
        <Link href="/about" className="transition-colors hover:text-[hsl(var(--accent))]" data-testid="link-about">Our story</Link>
      </nav>
      <div className="flex items-center gap-4">
        <button onClick={onSearch} aria-label="Search" data-testid="button-search"><Search size={18} strokeWidth={1.7}/></button>
        <button onClick={() => setDark(!dark)} aria-label="Toggle theme" data-testid="button-theme">{dark ? <Sun size={18} strokeWidth={1.7}/> : <Moon size={18} strokeWidth={1.7}/>}</button>
        <Link href="/cart" className="relative" aria-label="Cart" data-testid="link-cart"><ShoppingBag size={19} strokeWidth={1.7}/>{cartCount > 0 && <span className="absolute -right-2 -top-2 grid size-4 place-items-center rounded-full bg-[hsl(var(--accent))] text-[9px] font-bold text-[hsl(var(--primary-foreground))]">{cartCount}</span>}</Link>
        <Link href="/shop?wishlist=true" className="relative hidden sm:block" aria-label="Wishlist" data-testid="link-wishlist"><Heart size={18} strokeWidth={1.7}/>{wishlistCount > 0 && <span className="absolute -right-2 -top-2 grid size-4 place-items-center rounded-full bg-[hsl(var(--accent))] text-[hsl(var(--accent-foreground))] text-[9px] font-bold">{wishlistCount}</span>}</Link>
      </div>
    </div>
    <AnimatePresence>{menu && <motion.nav initial={{height:0,opacity:0}} animate={{height:'auto',opacity:1}} exit={{height:0,opacity:0}} className="overflow-hidden border-t hairline px-5 py-5 md:hidden">
      <div className="flex flex-col gap-4 text-xs font-semibold uppercase tracking-[.2em]">
        {['/shop','/collections','/quiz','/about','/contact'].map((href) => <button key={href} onClick={() => nav(href)} className="text-left">{href.slice(1).replace('-', ' ')}</button>)}
      </div>
    </motion.nav>}</AnimatePresence>
  </header>;
}

