function Toast({ toast, onClose }: { toast: ToastMessage|null; onClose:()=>void }) {
  useEffect(() => { if (toast) { const t = setTimeout(onClose, 2800); return () => clearTimeout(t); } return undefined; }, [toast, onClose]);
  return <AnimatePresence>{toast && <motion.div initial={{opacity:0,y:16}} animate={{opacity:1,y:0}} exit={{opacity:0,y:10}} className="fixed bottom-5 left-1/2 z-[70] flex -translate-x-1/2 items-center gap-3 border border-[hsl(var(--accent)/.4)] bg-[hsl(var(--secondary))] px-5 py-3 text-sm text-[hsl(var(--secondary-foreground))] shadow-2xl"><CheckCircle2 size={17} className="text-[hsl(var(--accent))]"/><div><strong className="block font-medium">{toast.title}</strong><span className="text-xs opacity-60">{toast.message}</span></div><button onClick={onClose} className="ml-3 opacity-50"><X size={15}/></button></motion.div>}</AnimatePresence>;
}

function ProductCard({ product, onAdd, onWish, wished, onQuick }: { product:Product; onAdd:(p:Product)=>void; onWish:(id:string)=>void; wished:boolean; onQuick:(p:Product)=>void }) {
  const [size, setSize] = useState(product.sizes[0]);
  return <motion.article layout className="product-card group relative" data-testid={`card-product-${product.id}`}>
    <div className="relative aspect-[.84] overflow-hidden bg-[hsl(var(--card))]">
      <Link href={`/product/${product.id}`} data-testid={`link-product-${product.id}`}><div className="product-image absolute inset-0" style={{backgroundImage:`url("${product.image}")`}}/></Link>
      <div className="absolute left-3 top-3 flex gap-2">{product.bestseller && <span className="bg-[hsl(var(--accent))] px-2 py-1 text-[hsl(var(--accent-foreground))] text-[9px] font-bold uppercase tracking-[.14em]">Bestseller</span>}{product.isNew && <span className="bg-[hsl(var(--secondary))] px-2 py-1 text-[9px] font-bold uppercase tracking-[.14em] text-[hsl(var(--secondary-foreground))]">New</span>}</div>
      <button onClick={() => onWish(product.id)} className={`absolute right-3 top-3 grid size-9 place-items-center bg-[hsl(var(--background)/.82)] text-[hsl(var(--foreground))] ${wished ? 'text-[hsl(var(--accent))]' : ''}`} aria-label="Toggle wishlist" data-testid={`button-wishlist-${product.id}`}><Heart size={17} fill={wished ? 'currentColor' : 'none'} strokeWidth={1.7}/></button>
      <div className="absolute inset-x-3 bottom-3 flex translate-y-3 gap-2 opacity-0 transition-all duration-300 group-hover:translate-y-0 group-hover:opacity-100"><button onClick={() => onQuick(product)} className="flex flex-1 items-center justify-center gap-2 bg-[hsl(var(--background)/.9)] py-3 text-[hsl(var(--foreground))] text-[10px] font-bold uppercase tracking-[.16em]" data-testid={`button-quick-view-${product.id}`}><Eye size={14}/> Quick view</button><button onClick={() => onAdd(product)} className="grid size-11 place-items-center bg-[hsl(var(--secondary))] text-[hsl(var(--secondary-foreground))]" aria-label="Add to cart" data-testid={`button-add-${product.id}`}><Plus size={17}/></button></div>
    </div>
    <div className="pt-4"><div className="mb-1 flex items-start justify-between gap-3"><Link href={`/product/${product.id}`} className="serif text-lg leading-tight hover:text-[hsl(var(--accent))]">{product.name}</Link><span className="text-xs">{money(size.price)}</span></div><div className="mb-3 flex items-center gap-2 text-[10px] uppercase tracking-[.12em] text-[hsl(var(--muted-foreground))]"><span>{product.family}</span><span className="size-1 rounded-full bg-[hsl(var(--accent))]"/><span>{product.collection.replace('The ','')}</span></div><div className="flex items-center gap-1 text-[hsl(var(--accent))]">{[0,1,2,3,4].map(i => <Star key={i} size={11} fill="currentColor"/>) }<span className="ml-1 text-[10px] text-[hsl(var(--muted-foreground))]">({product.reviews})</span></div></div>
    <select aria-label="Select size" value={size.size} onChange={(e) => setSize(product.sizes.find(s => s.size === e.target.value) || product.sizes[0])} className="sr-only" data-testid={`select-size-${product.id}`}>{product.sizes.map(s => <option key={s.size}>{s.size}</option>)}</select>
  </motion.article>;
}

function ProductModal({ product, onClose, onAdd }: { product:Product; onClose:()=>void; onAdd:(p:Product, size?:SizeOption)=>void }) {
  const [size, setSize] = useState(product.sizes[0]);
  return <motion.div className="fixed inset-0 z-[60] flex items-center justify-center bg-black/65 p-4" initial={{opacity:0}} animate={{opacity:1}} exit={{opacity:0}} onClick={onClose}>
    <motion.div initial={{opacity:0,scale:.97}} animate={{opacity:1,scale:1}} exit={{opacity:0,scale:.97}} onClick={e => e.stopPropagation()} className="grid max-h-[90vh] w-full max-w-3xl overflow-auto bg-[hsl(var(--background))] md:grid-cols-2">
      <div className="min-h-[340px] bg-cover bg-center" style={{backgroundImage:`url("${product.image}")`}}/>
      <div className="relative p-7 md:p-10"><button onClick={onClose} className="absolute right-5 top-5" aria-label="Close quick view" data-testid="button-close-modal"><X size={20}/></button><div className="eyebrow mb-3 text-[hsl(var(--accent))]">{product.collection}</div><h2 className="serif text-4xl">{product.name}</h2><p className="mt-4 text-sm leading-7 text-[hsl(var(--muted-foreground))]">{product.description}</p><div className="my-7 grid grid-cols-3 gap-3 border-y hairline py-5 text-xs"><div><span className="mb-1 block text-[10px] uppercase tracking-widest text-[hsl(var(--muted-foreground))]">Top</span>{product.top.join(' · ')}</div><div><span className="mb-1 block text-[10px] uppercase tracking-widest text-[hsl(var(--muted-foreground))]">Heart</span>{product.heart.join(' · ')}</div><div><span className="mb-1 block text-[10px] uppercase tracking-widest text-[hsl(var(--muted-foreground))]">Base</span>{product.base.join(' · ')}</div></div><div className="mb-7 flex gap-2">{product.sizes.map(s => <button key={s.size} onClick={() => setSize(s)} className={`border px-3 py-2 text-xs ${size.size===s.size ? 'border-[hsl(var(--accent))] bg-[hsl(var(--accent)/.13)]' : 'hairline'}`} data-testid={`button-modal-size-${s.size}`}>{s.size} · {money(s.price)}</button>)}</div><button onClick={() => { onAdd(product,size); onClose(); }} className="flex w-full items-center justify-center gap-2 bg-[hsl(var(--secondary))] py-4 text-xs font-bold uppercase tracking-[.17em] text-[hsl(var(--secondary-foreground))]" data-testid="button-modal-add"><ShoppingBag size={15}/> Add to bag</button><Link href={`/product/${product.id}`} onClick={onClose} className="mt-4 flex items-center justify-center gap-2 text-xs font-bold uppercase tracking-[.15em] text-[hsl(var(--accent))]">View full details <ArrowUpRight size={14}/></Link></div>
    </motion.div>
  </motion.div>;
}

